function groupPages(pages) {
  const groups = new Map();
  for (const page of pages) {
    const book = describePage(page);
    const items = groups.get(book.bookKey) || [];
    items.push({ page, book }); groups.set(book.bookKey, items);
  }
  return groups;
}

